using System;
using System.Net;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Concurrent;
using System.Text.Json;

namespace MonitoringAgent
{
    public sealed class AgentConfig
    {
        public string CollectorEndpoint { get; set; } = "https://metrics.internal.corp:9443/ingest";
        public int FlushIntervalMs { get; set; } = 5000;
        public int ShutdownTimeoutMs { get; set; } = 30000;
        public bool ValidateTls { get; set; } = true;
    }

    public sealed class DnsResolutionCache
    {
        private readonly ConcurrentDictionary<string, CachedEntry> _cache = new();
        private static readonly TimeSpan DefaultTtl = TimeSpan.FromMinutes(5);

        private record CachedEntry(IPAddress[] Addresses, DateTime ResolvedAt, TimeSpan Ttl);

        public async Task<IPAddress[]> ResolveAsync(string hostname)
        {
            if (_cache.TryGetValue(hostname, out var entry))
            {
                if (DateTime.UtcNow - entry.ResolvedAt < entry.Ttl)
                    return entry.Addresses;
            }

            var addresses = await Dns.GetHostAddressesAsync(hostname);
            _cache[hostname] = new CachedEntry(addresses, DateTime.UtcNow, DefaultTtl);
            return addresses;
        }

        public void Invalidate(string hostname) => _cache.TryRemove(hostname, out _);
        public void InvalidateAll() => _cache.Clear();
    }

    public sealed class MetricsBatcher
    {
        private readonly ConcurrentQueue<string> _buffer = new();
        private readonly SemaphoreSlim _flushLock = new(1, 1);

        public void Enqueue(string metric) => _buffer.Enqueue(metric);

        public async Task<string[]> DrainAsync()
        {
            await _flushLock.WaitAsync();
            try
            {
                var items = new System.Collections.Generic.List<string>();
                while (_buffer.TryDequeue(out var item))
                    items.Add(item);
                return items.ToArray();
            }
            finally
            {
                _flushLock.Release();
            }
        }
    }

    public sealed class LoggingAgent : IDisposable
    {
        private readonly AgentConfig _config;
        private readonly HttpClient _httpClient;
        private readonly DnsResolutionCache _dnsCache;
        private readonly MetricsBatcher _batcher;
        private readonly CancellationTokenSource _cts;
        private readonly Task _flushTask;
        private volatile bool _isShuttingDown;

        public LoggingAgent(AgentConfig config)
        {
            _config = config;
            _dnsCache = new DnsResolutionCache();
            _batcher = new MetricsBatcher();
            _cts = new CancellationTokenSource();

            var handler = new SocketsHttpHandler
            {
                ConnectCallback = async (context, ct) =>
                {
                    var host = context.DnsEndPoint.Host;
                    var addresses = await _dnsCache.ResolveAsync(host);
                    var socket = new System.Net.Sockets.Socket(
                        System.Net.Sockets.SocketType.Stream,
                        System.Net.Sockets.ProtocolType.Tcp);
                    await socket.ConnectAsync(addresses[0], context.DnsEndPoint.Port, ct);
                    return new System.Net.Sockets.NetworkStream(socket, ownsSocket: true);
                }
            };

            _httpClient = new HttpClient(handler);
            _flushTask = Task.Run(() => FlushLoopAsync(_cts.Token));
        }

        public void RecordMetric(string name, double value)
        {
            var metric = JsonSerializer.Serialize(new { name, value, ts = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() });
            _batcher.Enqueue(metric);
        }

        private async Task FlushLoopAsync(CancellationToken ct)
        {
            while (!ct.IsCancellationRequested)
            {
                try
                {
                    await Task.Delay(_config.FlushIntervalMs, ct);
                    await FlushAsync();
                }
                catch (OperationCanceledException) { break; }
                catch (Exception ex)
                {
                    Console.Error.WriteLine($"[Agent] Flush error: {ex.Message}");
                }
            }
        }

        private async Task FlushAsync()
        {
            var metrics = await _batcher.DrainAsync();
            if (metrics.Length == 0) return;

            var payload = JsonSerializer.Serialize(new { metrics, agent_id = Environment.MachineName });
            var content = new StringContent(payload, System.Text.Encoding.UTF8, "application/json");

            var response = await _httpClient.PostAsync(_config.CollectorEndpoint, content);
            if (!response.IsSuccessStatusCode)
                Console.Error.WriteLine($"[Agent] Collector returned {response.StatusCode}");
        }

        public async Task GracefulShutdownAsync()
        {
            _isShuttingDown = true;
            _cts.Cancel();

            // During shutdown, re-resolve DNS to handle failover endpoints
            _dnsCache.InvalidateAll();

            try
            {
                await _flushTask.WaitAsync(TimeSpan.FromMilliseconds(_config.ShutdownTimeoutMs));
            }
            catch (TimeoutException) { }

            // Final flush with fresh DNS resolution
            await FlushAsync();
        }

        public void Dispose()
        {
            _cts.Cancel();
            _httpClient.Dispose();
            _cts.Dispose();
        }
    }

    public class Program
    {
        public static async Task Main(string[] args)
        {
            var config = new AgentConfig();
            if (args.Length > 0) config.CollectorEndpoint = args[0];

            using var agent = new LoggingAgent(config);

            AppDomain.CurrentDomain.ProcessExit += async (s, e) =>
            {
                await agent.GracefulShutdownAsync();
            };

            Console.CancelKeyPress += async (s, e) =>
            {
                e.Cancel = true;
                await agent.GracefulShutdownAsync();
            };

            // Simulate metric collection
            while (true)
            {
                agent.RecordMetric("cpu.usage", Random.Shared.NextDouble() * 100);
                agent.RecordMetric("mem.used_mb", Random.Shared.Next(512, 8192));
                await Task.Delay(1000);
            }
        }
    }
}
